/// Modifies the given vector in-place, replacing negative values with 0.
/// Non-negative values remain unchanged.
pub fn zap_negatives(a: &mut Vec<i32>) {
    for x in a.iter_mut() {
        if *x < 0 {
            *x = 0;
        }
    }
}

